-- ==========================================
-- SHIFT SCHEDULE (Phase 17b)
--
-- No company_id/tenant_id column here, matching every other table in
-- this file (users, attendance, departments, designations, ...):
-- tenant isolation in this codebase is enforced by giving each
-- company its OWN database (see tenantProvisioningService.js), not by
-- a shared table filtered on a tenant column -- a row in THIS
-- database already belongs to exactly one company by construction.
--
-- Deliberately no UNIQUE(user_id, shift_date): a normal week only
-- ever has one row per employee per day (enforced at the application
-- layer in shiftScheduleController.js, which checks for an existing
-- row before creating a new one), but leaving the schema itself
-- unconstrained means a future split-shift phase (e.g. a morning row
-- and an evening row for the same employee/day) needs no migration.
-- ==========================================

CREATE TABLE "shift_schedule_history" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "shift_schedule_id" integer DEFAULT NULL,
  "user_id" integer DEFAULT NULL,
  "action" varchar NOT NULL CHECK ("action" IN ('created', 'updated', 'deleted')),
  "old_value" json DEFAULT NULL,
  "new_value" json DEFAULT NULL,
  "changed_by" integer DEFAULT NULL,
  "changed_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "shift_schedules" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "user_id" integer NOT NULL,
  "shift_date" date NOT NULL,
  "status" varchar NOT NULL DEFAULT 'working' CHECK ("status" IN ('working', 'off', 'leave')),
  "start_time" time DEFAULT NULL,
  "end_time" time DEFAULT NULL,
  "notes" text,
  "created_by" integer DEFAULT NULL,
  "updated_by" integer DEFAULT NULL,
  "created_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

