  "deleted_by" integer DEFAULT NULL,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "active_marker" integer GENERATED ALWAYS AS (CASE WHEN "status" = 'active' THEN 1 ELSE NULL END) STORED,
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_sprint_name_per_project" UNIQUE ("project_id","name"),
  CONSTRAINT "uq_one_active_sprint_per_project" UNIQUE ("project_id","active_marker"),


  CONSTRAINT "chk_sprint_dates" CHECK ((("end_date" is null) or ("start_date" is null) or ("end_date" >= "start_date")))
);

